import{_ as t,o,c as d,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"QEMU 测试","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/qemu-testing.md","filePath":"zh/dev/qemu-testing.md"}'),s={name:"zh/dev/qemu-testing.md"};function i(c,e,n,l,r,p){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="qemu-测试" tabindex="-1">QEMU 测试 <a class="header-anchor" href="#qemu-测试" aria-label="Permalink to &quot;QEMU 测试&quot;">​</a></h1><p>项目实际上如何在 QEMU 中测试 —— 发布门禁所用的同一套配方， 外加那些若靠踩坑学会会耗费数小时的 QEMU 特有行为（勘误、 固件路径、输入注入）。取证方法论见 <a href="./debug-handbook.html">debug-handbook.md</a>；套件机制见 <a href="./e2e-suites.html">e2e-suites.md</a>。</p><h2 id="_1-交互式启动" tabindex="-1">1. 交互式启动 <a class="header-anchor" href="#_1-交互式启动" aria-label="Permalink to &quot;1. 交互式启动&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios          # default: 512M, e1000 + user net, serial on stdio</span></span>
<span class="line"><span>make run-uefi          # OVMF via a pflash copy of OVMF_FD</span></span>
<span class="line"><span>make run-bios-gui      # GTK window (PS/2 keyboard receives scancodes)</span></span>
<span class="line"><span>make run-uefi-gui</span></span>
<span class="line"><span>make run-bios-persist  # -snapshot OFF: /etc edits persist in build/etc.img</span></span>
<span class="line"><span>make shot-bios         # VNC + monitor screendump -&gt; PNG (tools/qemu_shot_vnc.py)</span></span></code></pre></div><p><code>run-*</code> 目标会构建 ISO 和一个全新的 32 MiB FAT32 <code>/etc</code> 卷（<code>build/etc.img</code>），因此持久化测试从干净状态开始； persist 变体则刻意保留你的编辑。</p><h2 id="_2-ovmf-路径" tabindex="-1">2. OVMF 路径 <a class="header-anchor" href="#_2-ovmf-路径" aria-label="Permalink to &quot;2. OVMF 路径&quot;">​</a></h2><ul><li>默认：<code>OVMF_FD = $(OC_TOOLS)/share/ovmf/OVMF.fd</code> —— 由 工具链根推导（系统安装时为 <code>/usr</code>， <code>tools/install-toolchain.sh</code> 的免 root 沙箱中为 <code>&lt;tree&gt;/share/ovmf/OVMF.fd</code>）。</li><li><code>run-uefi</code> 目标把 <code>OVMF.fd</code> 复制到一个 pflash <em>工作</em>文件 （<code>-drive if=pflash,...OVMF_WORK.fd</code>），这样固件变量镜像 可写，而你原始的 <code>OVMF.fd</code> 永不被修改。</li><li>发布启动门禁在每次运行时都使用 FRESH 的 mktemp 日志、 通过 pflash CODE+VARS 运行 OVMF（BUG #63 假绿修复 —— 向旧日志追加会让死掉的启动看起来是绿的）。</li><li><code>QEMU_DATADIR</code>/<code>SEABIOS_DIR</code> 以同样方式跟随 <code>OC_TOOLS</code>， 分别供给 QEMU <code>-L</code> 与 BIOS 查找。</li></ul><h2 id="_3-确定性启动日志测试" tabindex="-1">3. 确定性启动日志测试 <a class="header-anchor" href="#_3-确定性启动日志测试" aria-label="Permalink to &quot;3. 确定性启动日志测试&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 tools/run_fix4_regression.py build/opencube.iso</span></span></code></pre></div><p>在 <code>-serial mon:stdio</code> 上跑 pexpect（latin-1、去 NUL、 去 ANSI、提示符 <code>(?:ush&gt;|oc&gt;)\\s</code>），然后执行带逐命令分节 断言的固定命令组。启动到 <code>ush&gt;</code> 提示符约需 2 秒墙上时间； 完整的 31 项检查在远不到一分钟内跑完。完整检查清单： <a href="./e2e-suites.html">e2e-suites.md</a> 第 2 节。</p><h2 id="_4-qemu-特有行为与勘误" tabindex="-1">4. QEMU 特有行为与勘误 <a class="header-anchor" href="#_4-qemu-特有行为与勘误" aria-label="Permalink to &quot;4. QEMU 特有行为与勘误&quot;">​</a></h2><p>与真实硬件不同的行为（均已在源码或内核内 trace 中验证）：</p><ul><li><strong>AHCI/NVMe 跳板缓冲是 QEMU 可见的契约</strong>：AHCI 通过 每端口一个 4 KiB 页对齐跳板缓冲执行 READ/WRITE DMA EXT， 按至多 8 扇区的分块切分（每块一条 PRDT 项）；NVMe 使用 一个带 64 位 PRP 的页跳板缓冲。若要改动存储驱动，请保持 跳板纪律 —— QEMU 的 DMA 引擎对 PRDT 对齐的严格程度 是某些真实控制器不具备的。</li><li><strong>PIIX3 prog-if 怪癖</strong>：ATA BMDMA 探测以任意 prog-if （掩码 0xFFFF00）匹配 IDE 类 0x0101，因为 QEMU 的 PIIX3 报告 0x80 而真实芯片报告 0x00/0x8A/... —— 仅按基类探测 会错误地锁到 IDE 控制器上。</li><li><strong>TCO 的存在性</strong>：Intel TCO 看门狗位于 <strong>q35</strong> 机型的 LPC 桥（ICH9-LPC，PCI 00:1f.0）上；默认 <code>pc</code> 机型 （PIIX3）没有 —— 探测会诚实地上报&quot;无&quot;。看门狗 E2E 场景以 <code>-no-reboot</code> 启动 q35。</li><li><strong>HDA + 44100 会冻住 VM</strong>：驱动在真实硬件上编程正确， 但在 QEMU 下整台 VM 冻结 —— 因此 <code>sample_rate_test</code> 只对该组合报告 caps 位。这一点被诚实上报，而非掩盖。</li><li><strong>HMP 截屏后串口 RX 字节丢失</strong>：QEMU 在 monitor 截屏 之后会间歇性丢失串口输入（已用内核内 RX trace 验证）。 因此功能测试轮次从不截图；抖动的检查会被隔离重跑 （<code>wp10_native_manual.py</code>）。</li><li><strong>4 GiB 以上的 xHCI DMA 被拒绝</strong>，发生在探测和每次传输时 —— 若 xHCI 设备&quot;消失&quot;，检查你的 <code>-m</code> 大小。</li><li><strong>Virtio-blk legacy 容量</strong>在配置偏移 0x14 处读取 （旧的 &quot;capacity = 0&quot; bug 的修复）。</li><li><strong>e1000 恢复</strong>：<code>net_e1000_resume()</code> 在 ACPI S3 之后 重放 legacy e1000 寄存器编程（QEMU 会在挂起时复位 NIC）。</li><li><strong>显示</strong>：MB2 头请求 800x600x32；UEFI-GOP 交接 RGBX 而 BIOS-VBE 交接 BGRX —— <code>screen_fb_rgb</code> 从 GRUB tag 推导 掩码，因此两者都能工作。</li><li><strong>热复位保留 DRAM</strong>：启动状态孤岛 0x98000/0x9B000 能 在 QEMU 热复位后存活（E820 保留，经实证）；冷启动会清除 它们，且每个读取方都会先校验魔数。</li></ul><h2 id="_5-驱动-ocbl-启动菜单-sendkey" tabindex="-1">5. 驱动 OCBL 启动菜单（sendkey） <a class="header-anchor" href="#_5-驱动-ocbl-启动菜单-sendkey" aria-label="Permalink to &quot;5. 驱动 OCBL 启动菜单（sendkey）&quot;">​</a></h2><p>OCBL 启动菜单（树内引导加载程序，10 秒倒计时）读取 PS/2 按键 —— 它先于内核、先于任何串口控制台存在。在 无头 QEMU 中你通过 HMP monitor 驱动它：</p><ul><li>以 <code>-monitor stdio</code>（或测试装置所用的 unix-socket monitor）连同 <code>-serial stdio</code> 启动 QEMU。</li><li><code>sendkey down</code> / <code>sendkey up</code> 移动高亮；<code>sendkey ret</code> 启动所选条目；倒计时 10 秒后启动默认项。</li><li>在菜单中选择 OCIRE 条目会写入一条 USER_REQUEST 记录 （这正是 OCIRE 上报的区别：&quot;由用户请求&quot; vs 判定为故障 并给出修复建议）—— WP04/WP07a 证据记录中的交互式 sendkey 会话驱动的正是这一点。</li><li>同一条 <code>sendkey</code> 通道也是各套件把串口链路无法承载的 按键（方向键、Home/End）送入<em>客户机</em>的方式（行编辑器 与编辑器测试）；指针输入走 QMP <code>input-send-event</code> （<code>-display none</code> + QEMU 10 上 HMP mouse_move 已失效）。</li></ul><h2 id="_6-截图" tabindex="-1">6. 截图 <a class="header-anchor" href="#_6-截图" aria-label="Permalink to &quot;6. 截图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make shot-bios     # boot screenshot to build/shot-bios.png (VNC + PIL)</span></span>
<span class="line"><span>make shot-uefi</span></span></code></pre></div><p>帧缓冲断言（回归检查 1）要求 PPM 截屏显示 &gt;= 2 种颜色 和可测的前景比例 —— 曾经有一道仅看串口的门禁在死面板上 通过，因此截图是活着的显示的<em>唯一</em>被接受的证明，而功能 轮次因上述串口 RX 勘误避开截图。</p><h2 id="_7-与驱动对应的-qemu-设备" tabindex="-1">7. 与驱动对应的 QEMU 设备 <a class="header-anchor" href="#_7-与驱动对应的-qemu-设备" aria-label="Permalink to &quot;7. 与驱动对应的 QEMU 设备&quot;">​</a></h2><table tabindex="0"><thead><tr><th>QEMU 标志</th><th>内核驱动</th></tr></thead><tbody><tr><td><code>-device e1000</code>（默认网络）</td><td>e1000 NIC（内建路径）</td></tr><tr><td><code>-device e1000e</code> 等</td><td>WP-10b 框架家族</td></tr><tr><td><code>-device virtio-blk-pci</code></td><td>virtio-blk（<code>vda</code>）</td></tr><tr><td><code>-device nvme</code></td><td>NVMe（<code>nvme0</code>）</td></tr><tr><td><code>-device ahci</code> + SATA 磁盘</td><td>AHCI（<code>sda</code>...）</td></tr><tr><td>IDE 磁盘</td><td>ATA PIO + Bus-Master DMA（<code>hda</code>..）</td></tr><tr><td>经 xHCI 的 <code>-device usb-storage</code></td><td>USB MSC（注册块设备）</td></tr><tr><td><code>-device AC97</code> / <code>-device intel-hda</code> + <code>-device hda-output</code></td><td>声音</td></tr><tr><td><code>-device virtio-sound-pci</code></td><td>virtio-snd</td></tr><tr><td>q35 机型</td><td>Intel TCO 看门狗</td></tr><tr><td><code>-bios OVMF.fd</code> / pflash</td><td>UEFI 启动路径</td></tr><tr><td>LSI 53C895A（<code>-device lsi</code>）</td><td>SCSI（相机族 <code>scsi</code> op）</td></tr><tr><td><code>-acpitable file=wdat.bin</code></td><td>ACPI WDAT 看门狗（tools/make_wdat_table.py）</td></tr></tbody></table><h2 id="_8-速度" tabindex="-1">8. 速度 <a class="header-anchor" href="#_8-速度" aria-label="Permalink to &quot;8. 速度&quot;">​</a></h2><ul><li>每次自动化运行都用 <code>-display none -serial mon:stdio</code>。</li><li>在回归环境中启动到 <code>ush&gt;</code> 提示符约需 2 秒墙上时间。</li><li>编译缓存（<code>tools/oc_cc.sh</code>）让<em>构建</em>内循环保持热态； 见 <a href="./build.html">build.md</a> 第 7 节。</li><li><code>-icount</code> 为网络测试提供时序稳定性；可重现构建意味着 两次复现的崩溃两次都是相同字节。</li></ul>`,23)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
